const LYRICS_HI = {
  emr:`एहि मुरारे

एहि मुरारे कुञ्जबिहारि
एहि प्रणत तव बन्धो
हे माधव मधु मथन वरेण्य
केशव करुणा सिन्धो

रास निकुञ्जे गुञ्जति नियतं
भ्रमरशतं किल कान्त
एहि निभृत पथ पान्थ
त्वामिह याछे दरशन दानम्
हे मधुसूदन शान्त

नव नीरज धर श्यामल सुन्दर
चन्द्र कुसुम रुचिवेश
गोपिगण हृदयेश
गोवर्धन धर वृन्दावन चर
वंशीधर परमेश

राधा रञ्जन कंस निषूदन
प्रण तिस्तावक चरणे
निखिल निराश्रय शरणे
एहि जनार्दन पिताम्बर धर
कुञ्जे मन्थर पवने`,
  gsn:`श्री गोपाल सहस्रनाम स्तोत्रम्

ॐ क्लीं देवः कामदेवः कामबीजशिरोमणिः।
श्रीगोपालो महीपालः सर्ववेदांगपारगः ॥1॥

धरणीपालको धन्यः पुण्डरीकः सनातनः ।
गोपतिर्भूपतिः शास्ता प्रहर्ता विश्वतोमुखः ॥2॥

आदिकर्ता महाकर्ता महाकालः प्रतापवान् ।
जगज्जीवो जगद्धाता जगद्भर्ता जगद्वसुः ॥3॥

मत्स्यो भीमः कुहूभर्ता हर्ता वाराहमूर्तिमान् ।
नारायणो हृषीकेशो गोविन्दो गरुडध्वजः ॥4॥

गोकुलेन्द्रो महाचन्द्रः शर्वरीप्रियकारकः।
कमलामुखलोलाक्षः पुण्डरीक शुभावहः ॥5॥

दुर्वासाः कपिलो भौमः सिन्धुसागरसंगमः।
गोविन्दो गोपतिर्गोत्र: कालिन्दीप्रेमपूरकः ॥6॥

गोपस्वामी गोकुलेन्द्रो गोवर्धनवरप्रदः।
नन्दादिगोकुलत्राता दाता दारिद्र्यभञ्जनः ॥7॥

सर्वमंगलदाता च सर्वकामप्रदायकः।
आदिकर्ता महीभर्ता सर्वसागरसिन्धुजः ॥8॥

गजगामी गजोद्धारी कामी कामकलानिधिः।
कलंकरहितश्चन्द्रो बिम्बास्यो बिम्बसत्तमः ॥9॥

मालाकारः कृपाकारः कोकिलास्वरभूषणः।
रामो नीलाम्बरो देवो हली दुर्दममर्दनः ॥10॥

सहस्राक्षपुरीभेत्ता महामारीविनाशनः।
शिवः शिवतमो भेत्ता बलारातिप्रपूजकः ॥11॥

कुमारीवरदायी च वरेण्यो मीनकेतनः।
नरो नारायणो धीरो राधापतिरुदारधीः ॥12॥

श्रीपतिः श्रीनिधिः श्रीमान् मापतिः प्रतिराजहा।
वृन्दापतिः कुलग्रामी धामी ब्रह्म सनातनः ॥13॥

रेवतीरमणो रामश्चंचलश्चारुलोचनः।
रामायणशरीरोऽयं रामी रामः श्रियः पतिः ॥14॥

शर्वरः शर्वरी शर्वः सर्वत्र शुभदायकः।
राधाराधयितो राधी राधाचित्तप्रमोदकः ॥15॥

राधारतिसुखोपेतो राधामोहनतत्परः।
राधावशीकरो राधाहृदयांभोजषट्पदः ॥16॥

राधालिंगनसंमोहो राधानर्तनकौतुकः।
राधासंजातसम्प्रीती राधाकामफलप्रदः ॥17॥

वृन्दापतिः कोशनिधिः कोकशोकविनाशकः।
चन्द्रापतिश्चन्द्रपतिश्चण्डकोदण्डभंजनः ॥18॥

रामो दाशरथी रामो भृगुवंशसमुद्भवः।
आत्मारामो जितक्रोधो मोहो मोहान्धभंजनः ॥19॥

वृषभानुर्भवो भावः काश्यपिः करुणानिधिः।
कोलाहलो हली हाली हेली हलधरप्रियः ॥20॥

राधामुखाब्जमार्तण्डो भास्करो रविजो विधुः।
विधिर्विधाता वरुणो वारुणो वारुणीप्रियः ॥21॥

रोहिणीहृदयानन्दी वसुदेवात्मजो बली।
नीलाम्बरो रौहिणेयो जरासन्धवधोऽमलः ॥22॥

नागो नवाम्भो विरुदो वीरहा वरदो बली ।
गोपथो विजयी विद्वान् शिपिविष्टः सनातनः ॥23॥

पर्शुरामवचोग्राही वरग्राही श्रृगालहा।
दमघोषोपदेष्टा च रथग्राही सुदर्शनः ॥24॥

वीरपत्नीयशस्त्राता जराव्याधिविघातकः।
द्वारकावासतत्त्वज्ञो हुताशनवरप्रदः ॥25॥

यमुनावेगसंहारी नीलाम्बरधरः प्रभुः।
विभुः शरासनो धन्वी गणेशो गणनायकः ॥26॥

लक्ष्मणो लक्षणो लक्ष्यो रक्षोवंशविनाशनः ।
वामनो वामनीभूतो वमनो वमनारूहः ॥27॥

यशोदानन्दनः कर्ता यमलार्जुनमुक्तिदः ।
उलूखली महामानी दामबद्धाह्वयी शमी ॥28॥

भक्तानुकारी भगवान् केशवोऽचलधारकः ।
केशिहा मधुहा मोही वृषासुरविघातकः ॥29॥

अघासुरविनाशी च पूतनामोक्षदायकः ।
कुब्जाविनोदी भगवान् कंसमृत्युर्महामखी ॥30॥

अश्वमेधो वाजपेयो गोमेधो नरमेधवान्।
कन्दर्पकोटिलावण्यश्चन्द्रकोटिसुशीतलः ॥31॥

रविकोटिप्रतीकाशो वायुकोटिमहाबलः।
ब्रह्मा ब्रह्माण्डकर्ता च कमलावांछितप्रदः ॥32॥

कमला कमलाक्षश्च कमलामुखलोलुपः।
कमलाव्रतधारी च कमलाभः पुरन्दरः ॥33॥

सौभाग्याधिकचित्तोऽयं महामायी महोत्कटः।
तारकारिः सुरत्राता मारीचक्षोभकारकः ॥34॥

विश्वामित्रप्रियो दान्तो रामो राजीवलोचनः ।
लंकाधिपकुलध्वंसी विभीषणवरप्रदः ॥35॥

सीतानन्दकरो रामो वीरो वारिधिबन्धनः ।
खरदूषणसंहारी साकेतपुरवासनः ॥36॥

चन्द्रावलीपतिः कूल: केशी कंसवधोऽमरः।
माधवो मधुहा माध्वी माध्वीको माधवो मधुः ॥37॥

मुंजाटवीगाहमानो धेनुकारिर्धरात्मजः।
वंशी वटबिहारी च गोवर्धनवनाश्रयः ॥38॥

तथा तालवनोद्देशी भाण्डीरवनशंखहा ।
तृणावर्तकथाकारी वृषभानुसुतापतिः ॥39॥

राधाप्राणसमो राधावदनाब्जमधुव्रतः ।
गोपीरंजनदैवज्ञो लीलाकमलपूजितः ॥40॥

क्रीडाकमलसन्दोहो गोपिकाप्रीतिरंजनः ।
रंजको रंजनो रङ्गो रंगी रंगमहीरुहः ॥41॥

कामः कामारिभक्तोऽयं पुराणपुरुषः कविः ।
नारदो देवलो भीमो बालो बालमुखाम्बुजः ॥42॥

अम्बुजो ब्रह्मसाक्षी च योगी दत्तवरो मुनिः।
ऋषभः पर्वतो ग्रामो नदीपवनवल्लभः ॥43॥

पद्मनाभः सुरज्येष्ठो ब्रह्मा रुद्रोऽहिभूषितः।
गणानां त्राणकर्ता च गणेशो ग्रहिलो ग्रही ॥44॥

गणाश्रयो गणाध्यक्षः क्रोडीकृतजगत्रयः।
यादवेन्द्रो द्वारकेन्द्रो मथुरावल्लभो धुरी ॥45॥

भ्रमरः कुन्तली कुन्तीसुतरक्षी महामखी।
यमुनावरदाता च काश्यपस्य वरप्रदः ॥46॥

शड्खचूडवधोद्दामो गोपीरक्षणतत्परः ।
पांचजन्यकरो रामी त्रिरामी वनजो जयः ॥47॥

फाल्गुनः फाल्गुनसखो विराधवधकारकः ।
रुक्मिणीप्राणनाथश्च सत्यभामाप्रियंकरः ॥48॥

कल्पवृक्षो महावृक्षो दानवृक्षो महाफलः।
अंकुशो भूसुरो भामो भामको भ्रामकोहरिः ॥49॥

सरलः शाश्वतो वीरो यदुवंशी शिवात्मकः।
प्रद्युम्नो बलकर्ता च प्रहर्ता दैत्यहा प्रभुः ॥50॥

महाधनो महावीरो वनमालाविभूषणः।
तुलसीदामशोभाढयो जालन्धरविनाशनः ॥51॥

शूरः सूर्यो मृकण्डश्च भास्करो विश्वपूजितः।
रविस्तमोहा वह्निश्च वाडवो वडवानलः ॥52॥

दैत्यदर्पविनाशी च गरुडो गरुडाग्रजः।
गोपीनाथो महीनाथो वृन्दानाथोऽवरोधकः ॥53॥

प्रपंची पंचरूपश्च लतागुल्मश्च गोपतिः ।
गंगा च यमुनारूपो गोदा वेत्रवती तथा ॥54॥

कावेरी नर्मदा तापी गण्डकी सरयूस्तथा ।
राजसस्तामसः सत्त्वी सर्वांगी सर्वलोचनः ॥55॥

सुधामयोऽमृतमयो योगिनीवल्लभः शिवः ।
बुद्धो बुद्धिमतां श्रेष्ठो विष्णुर्जिष्णुः शचीपतिः ॥56॥

वंशी वंशधरो लोको विलोको मोहनाशनः ।
रवरावो रवो रावो बालो बालबलाहकः ॥57॥

शिवो रुद्रो नलो नीलो लाङ्गली लाङ्गलाश्रयः ।
पारदः पावनो हंसो हंसारूढो जगत्पतिः ॥58॥

मोहिनीमोहनो मायी महामायो महामखी ।
वृषो वृषाकपिः कालः कालीदमनकारकः ॥59॥

कुब्जाभाग्यप्रदो वीरो रजकक्षयकारकः ।
कोमलो वारुणो राजा जलजो जलधारकः ॥60॥

हारकः सर्वपापघ्नः परमेष्ठी पितामहः।
खड्गधारी कृपाकारी राधारमणसुन्दरः ॥61॥

द्वादशारण्यसम्भोगी शेषनागफणालयः।
कामः श्यामः सुखः श्रीदः श्रीपतिः श्रीनिधिः कृतिः ॥62॥

हरिर्हरो नरो नारो नरोत्तम इषुप्रियः।
गोपालीचित्तहर्ता च कर्ता संसारतारकः ॥63॥

आदिदेवो महादेवो गौरीगुरुरनाश्रयः ।
साधुर्मधुर्विधुर्धाता भ्राता क्रूरपरायणः ॥64॥

रोलम्बी च हयग्रीवो वानरारिर्वनाश्रयः ।
वनं वनी वनाध्यक्षो महावंद्यो महामुनिः ॥65॥

स्यमन्तकमणिप्राज्ञो विज्ञो विघ्नविघातकः ।
गोवर्धनो वर्धनीयो वर्धनी वर्धनप्रियः ॥66॥

वर्धन्यो वर्धनो वर्धी वार्धिन्यः सुमुखप्रियः।
वर्धितो वृद्धको वृद्धो वृन्दारकजनप्रियः ॥67॥

गोपालरमणीभर्ता साम्बकुष्ठविनाशनः।
रुक्मिणीहरणः प्रेम-प्रेमी चन्द्रावलीपतिः ॥68॥

श्रीकर्ता विश्वभर्ता च नरो नारायणो बली।
गणो गणपतिश्चैव दत्तात्रेयो महामुनिः ॥69॥

व्यासो नारायणो दिव्यो भव्यो भावुकधारकः ।
स्वः श्रेयसं शिवं भद्रं भावुकं भविकं शुभम् ॥70॥

शुभात्मकः शुभः शास्ता प्रशास्ता मेघनादहा ।
ब्रह्मण्यदेवो दीनानामुद्धारकरणक्षमः ॥71॥

कृष्णः कमलपत्राक्षः कृष्णः कमललोचनः।
कृष्णः कामी सदाकृष्णः समस्तप्रियकारकः ॥72॥

नन्दो नन्दी महानन्दी मादी मादनकः किली ।
मिली हिली गिली गोली गोलो गोलालयो गुली ॥73॥

गुग्गुली मारकी शाखी वटः पिप्पलकः कृती ।
म्लेच्छहा कालहर्ता च यशोदायश एव च ॥74॥

अच्युतः केशवो विष्णुर्हरिः सत्यो जनार्दनः ।
हंसो नारायणो लीलो नीलो भक्तिपरायणः ॥75॥

जानकीवल्लभो रामो विरामो विघ्ननाशनः ।
सहस्रांशुर्महाभानुर्वीरबाहुर्महोदधिः ॥76॥

समुद्रोऽब्धिरकूपारः पारावारः सरित्पतिः ।
गोकुलानन्दकारी च प्रतिज्ञापरिपालकः ॥77॥

सदारामः कृपारामो महारामो धनुर्धरः ।
पर्वतः पर्वताकारो गयो गेयो द्विजप्रियः ॥78॥

कम्बलाश्वतरो रामो रामायणप्रवर्तकः ।
द्यौर्दिवौ दिवसो दिव्यो भव्यो भाविभयापहः ॥79॥

पार्वतीभाग्यसहितो भ्राता लक्ष्मीविलासवान् ।
विलासी साहसी सर्वी गर्वी गर्वितलोचनः ॥80॥

मुरारिर्लोकधर्मज्ञो जीवनो जीवनान्तकः ।
यमो यमादिर्यमनो यामी यामविधायकः ॥81॥

वंसुली पांसुली पांसुः पाण्डुरर्जुनवल्लभः ।
ललिताचन्द्रिकामाली माली मालाम्बुजाश्रयः ॥82॥

अम्बुजाक्षो महायक्षो दक्षश्चिन्तामणिप्रभुः ।
मणिर्दिनमणिश्चैव केदारो बदराश्रयः ॥83॥

बदरीवनसम्प्रीतो व्यासः सत्यवतीसुतः ।
अमरारिनिहन्ता च सुधासिन्धुर्विधूदयः ॥84॥

चन्द्रो रविः शिवः शूली चक्री चैव गदाधरः ।
श्रीकर्ता श्रीपतिः श्रीदः श्रीदेवो देवकीसुतः ॥85॥

श्रीपतिः पुण्डरीकाक्षः पद्मनाभो जगत्पतिः ।
वासुदेवोऽप्रमेयात्मा केशवो गरुडध्वजः ॥86॥

नारायणः परं धाम देवदेवो महेश्वरः ।
चक्रपाणिः कलापूर्णो वेदवेद्यो दयानिधिः ॥87॥

भगवान्सर्वभूतेशो गोपालः सर्वपालकः ।
अनन्तो निर्गुणोऽनन्तो निर्विकल्पो निरंजनः ॥88॥

निराधारो निराकारो निराभासो निराश्रयः ।
पुरुषः प्रणवातीतो मुकुन्दः परमेश्वरः ॥89॥

क्षणावनिः सार्वभौमो वैकुण्ठो भक्तवत्सलः ।
विष्णुर्दामोदरः कृष्णो माधवो मथुरापतिः ॥90॥

देवकीगर्भसम्भूतो यशोदावत्सलो हरिः ।
शिवः संकर्षणः शम्भुर्भूतनाथो दिवस्पतिः ॥91॥

अव्ययः सर्वधर्मज्ञो निर्मलो निरुपद्रवः ।
निर्वाणनायको नित्यो निलजीमूतसन्निभः ॥92॥

कलाक्षयश्च सर्वज्ञः कमलारुपतत्परः ।
हृषीकेशः पीतवासो वसुदेवप्रियात्मजः ॥93॥

नन्दगोपकुमारार्यो नवनीताशनः प्रभुः ।
पुराणपुरुषः श्रेष्ठः शङ्खपाणिः सुविक्रमः ॥94॥

अनिरुद्धश्चक्ररथः शार्ङ्गपाणिश्चतुर्भुजः ।
गदाधरः सुरार्तिघ्नो गोविन्दो नन्दकायुधः ॥95॥

वृन्दावनचरः शौरिर्वेणुवाद्यविशारदः ।
तृणावर्तान्तको भीमो साहसो बहुविक्रमः ॥96॥

शकटासुरसंहारी बकासुरविनाशनः ।
धेनुकासुरसंघातः पूतनारिर्नृकेसरी ॥97॥

पितामहो गुरुः साक्षी प्रत्यगात्मा सदाशिवः ।
अप्रमेयः प्रभुः प्राज्ञोऽप्रतर्क्यः स्वप्न वर्धनः ॥98॥

धन्यो मान्यो भवो भावो धीरः शान्तो जगद्गुरुः।
अन्तर्यामीश्वरो दिव्यो दैवज्ञो देवता गुरुः॥99॥

क्षीराब्धिशयनो धाता लक्ष्मीवॉल्लक्ष्मणाग्रजः।
धात्रीपतिरमेयात्मा चन्द्रशेखरपूजितः॥100॥

लोकसाक्षी जगच्चक्षुः पुण्यचारित्रकीर्तनः।
कोटिमन्मथसौन्दर्यो जगन्मोहनविग्रहः ॥101॥

मन्दस्मिततमो गोपो गोपिका परिवेष्टितः।
फुल्लारविन्दनयनश्चाणूरान्ध्रनिषूदनः ॥102॥

इन्दीवरदलश्यामो बर्हिबर्हावतंसकः।
मुरलीनिनदाह्लादो दिव्यमाल्याम्बराश्रयः ॥103॥

सुकपोलयुगः सुभ्रूयुगलः सुललाटकः।
कम्बुग्रीवो विशालाक्षो लक्ष्मीवान् शुभलक्षणः ॥104॥

पीनवक्षाश्चतुर्बाहुश्चतुर्मूर्तिस्त्रिविक्रमः।
कलंकरहितः शुद्धो दुष्टशत्रुनिबर्हणः ॥105॥

किरीटकुण्डलधरः कटकाङ्गदमण्डितः।
मुद्रिकाभरणोपेतः कटिसूत्रविराजितः ॥106॥

मंजीररंजितपदः सर्वाभरणभूषितः।
विन्यस्तपादयुगलो दिव्यमंगलविग्रहः ॥107॥

गोपिकानयनानन्दः पूर्णचन्द्रनिभाननः।
समस्तजगदानन्दः सुन्दरो लोकनन्दनः ॥108॥

यमुनातीरसंचारी राधामन्मथवैभवः।
गोपनारीप्रियो दान्तो गोपिवस्त्रापहारकः ॥109॥

श्रृंगारमूर्तिः श्रीधामा तारको मूलकारणम्।
सृष्टिसंरक्षणोपायः क्रूरासुरविभंजनः ॥110॥

नरकासुरहारी च मुरारिर्वैरिमर्दनः।
आदितेयप्रियो दैत्यभीकरश्चेन्दुशेखरः ॥111॥

जरासन्धकुलध्वंसी कंसारातिः सुविक्रमः।
पुण्यश्लोकः कीर्तनीयो यादवेन्द्रो जगन्नुतः ॥112॥

रुक्मिणीरमण: सत्यभामाजाम्बवतीप्रियः।
मित्रविन्दानाग्नजितीलक्ष्मणासमुपासितः ॥113॥

सुधाकरकुले जातोऽनन्तप्रबलविक्रमः।
सर्वसौभाग्यसम्पन्नो द्वारकायामुपस्थितः ॥114॥

भद्रासूर्यसुतानाथो लीलामानुषविग्रहः।
सहस्रषोडशस्त्रीशो भोगमोक्षैकदायकः ॥115॥

वेदान्तवेद्यः संवेद्यो वैद्यो ब्रह्माण्डनायकः।
गोवर्धनधरो नाथः सर्वजीवदयापरः ॥116॥

मूर्तिमान्सर्वभूतात्मा आर्तत्राणपरायणः।
सर्वज्ञः सर्वसुलभः सर्वशास्त्रविशारदः ॥117॥

षड्गुणैश्चर्यसम्पन्नः पूर्णकामो धुरन्धरः।
महानुभावः कैवल्यदायको लोकनायकः ॥118॥

आदिमध्यान्तरहितः शुद्धसात्त्विकविग्रहः।
असमानः समस्तात्मा शरणागतवत्सलः ॥119॥

उत्पत्तिस्थितिसंहारकारणं सर्वकारणम्।
गंभीरः सर्वभावज्ञः सच्चिदानन्दविग्रहः ॥120॥

विष्वक्सेनः सत्यसन्धः सत्यवान्सत्यविक्रमः।
सत्यव्रतः सत्यसंज्ञः सर्वधर्मपरायणः ॥121॥

आपन्नार्तिप्रशमनो द्रौपदीमानरक्षकः।
कन्दर्पजनकः प्राज्ञो जगन्नाटकवैभवः ॥122॥

भक्तिवश्यो गुणातीतः सर्वैश्वर्यप्रदायकः।
दमघोषसुतद्वेषी बाणबाहुविखण्डनः ॥123॥

भीष्मभक्तिप्रदो दिव्यः कौरवान्वयनाशनः।
कौन्तेयप्रियबन्धुश्च पार्थस्यन्दनसारथिः ॥124॥

नारसिंहो महावीरः स्तम्भजातो महाबलः।
प्रह्लादवरदः सत्यो देवपूज्योऽभयङ्करः ॥125॥

उपेन्द्र इन्द्रावरजो वामनो बलिबन्धनः।
गजेन्द्रवरदः स्वामी सर्वदेवनमस्कृतः ॥126॥

शेषपर्यङ्कशयनो वैनतेयरथो जयी।
अव्याहतबलैश्वर्यसम्पन्नः पूर्णमानसः ॥127॥

योगेश्वरेश्वरः साक्षी क्षेत्रज्ञो ज्ञानदायकः।
योगिहृत्पङ्कजावासो योगमायासमन्वितः ॥128॥

नादबिन्दुकलातीतश्चतुर्वर्गफलप्रदः।
सुषुम्णामार्गसंचारी देहस्यान्तरसंस्थितः ॥129॥

देहेन्द्रियमनः प्राणसाक्षी चेतः प्रसादकः।
सूक्ष्मः सर्वगतो देहीज्ञानदर्पणगोचरः ॥130॥

तत्त्वत्रयात्मकोऽव्यक्तः कुण्डलीसमुपाश्रितः।
ब्रह्मण्यः सर्वधर्मज्ञः शान्तो दान्तो गतक्लमः ॥131॥

श्रीनिवासः सदानन्दो विश्वमूर्तिर्महाप्रभुः।
सहस्रशीर्षा पुरुषः सहस्राक्षः सहस्रपात् ॥132॥

समस्तभुवनाधारः समस्तप्राणरक्षकः।
समस्तसर्वभावज्ञो गोपिकाप्राणवल्लभः ॥133॥

नित्योत्सवो नित्यसौख्यो नित्यश्रीर्नित्यमंगलः।
व्यूहार्चितो जगन्नाथः श्रीवैकुण्ठपुराधिपः ॥134॥

पूर्णानन्दघनीभूतो गोपवेषधरो हरिः।
कलापकुसुमश्यामः कोमलः शान्तविग्रहः ॥135॥

गोपाङ्गनावृतोऽनन्तो वृन्दावनसमाश्रयः।
वेणुवादरतः श्रेष्ठो देवानां हितकारकः ॥136॥

बालक्रीडासमासक्तो नवनीतस्य तस्करः।
गोपालकामिनीजारश्चोरजारशिखामणिः ॥137॥

परं ज्योतिः पराकाशः परावासः परिस्फुटः।
अष्टादशाक्षरो मन्त्रो व्यापको लोकपावनः ॥138॥

सप्तकोटिमहामंत्रशेखरो देवशेखरः।
विज्ञानज्ञानसन्धानस्तेजोराशिर्जगत्पतिः ॥139॥

भक्तलोकप्रसन्नात्मा भक्तमन्दारविग्रहः।
भक्तदारिद्रयदमनो भक्तानां प्रीतिदायकः ॥140॥

भक्ताधीनमनाः पूज्यो भक्तलोकशिवङ्करः।
भक्ताभीष्टप्रदः सर्वभक्ताघौघनिकृन्तनः ॥141॥

अपारकरुणासिन्धुर्भगवान्भक्ततत्परः
जै जै श्रीसम्मोहनतंत्रे पार्वतीश्वरसंवादे श्रीगोपालसहस्रनामस्तोत्रं की जै जै श्रीहित हरिवंश ॥142॥

स्रोत: https://bhajanmarg.com/gopal-sahastranaam-stotram/`,
  nsh:`निर्वाणषट्कम्

मनोबुद्ध्यहङ्कारचित्तानि नाहं
न च श्रोत्रजिह्वे न च घ्राणनेत्रे।
न च व्योम भूमिर्न तेजो न वायुः
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥

न च प्राणसंज्ञो न वै पञ्चवायुः
न वा सप्तधातुर्न वा पञ्चकोशः।
न वाक्पाणिपादं न चोपस्थपायू
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥

न मे द्वेषरागौ न मे लोभमोहौ
न मे वै मदो नैव मात्सर्यभावः।
न धर्मो न चार्थो न कामो न मोक्षः
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥

न पुण्यं न पापं न सौख्यं न दुःखम्
न मन्त्रो न तीर्थं न वेदा न यज्ञाः।
अहं भोजनं नैव भोज्यं न भोक्ता
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥

न मे मृत्युशङ्का न मे जातिभेदः
पिता नैव मे नैव माता न जन्म।
न बन्धुर्न मित्रं गुरुर्नैव शिष्यः
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥

अहं निर्विकल्पो निराकाररूपो
विभुत्वाच्च सर्वत्र सर्वेन्द्रियाणाम्।
न चासङ्गतं नैव मुक्तिर्न मेयः
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥

चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥`,
  gsk:`सखि हे केशिमथनमुदारम्

⟦RED⟧सखि हे केशि-मथनम् उदारम्।
⟦RED⟧रमय मया सह मदन-मनोरथ-भावितया स-विकारम्॥
अनुवाद: हे सखी, केशी दैत्य का वध करने वाले उदार श्रीकृष्ण को मेरे साथ मिलाओ—मैं प्रेम की कामना से आकुल और भावों से विह्वल हूँ।

⟦RED⟧निभृत-निकुञ्ज-गृहं गतया निशि रहसि निलीय वसन्तम्।
⟦RED⟧चकित-विलोकित-सकल-दिशा रति-रभस-भरेण हसन्तम् ॥ १ ॥
अनुवाद: रात्रि में जब मैं निर्जन निकुञ्ज-गृह में गई, तब वे छिपकर बैठे थे; मैं चकित दृष्टि से सब दिशाओं में देख रही थी और वे प्रेम की उत्सुकता के अतिरेक से हँस रहे थे—(उन कृष्ण को मेरे साथ मिलाओ)।

⟦RED⟧प्रथम-समागम-लज्जितया पटु-चाटु-शतैर् अनुकूलम्।
⟦RED⟧मृदु-मधुर-स्मित-भाषितया शिथिली-कृत-जघन-दुकूलम् ॥ २ ॥
अनुवाद: प्रथम मिलन में मैं लज्जित थी; उन्होंने सैकड़ों चतुर प्रिय वचनों से मुझे अनुकूल कर लिया। मैं मृदु-मधुर मुस्कान के साथ बोल रही थी और उन्होंने मेरा कटि-वस्त्र शिथिल कर दिया—(उन कृष्ण को…)।

⟦RED⟧किसलय-शयन-निवेशितया चिरम् उरसि ममैव शयानम्।
⟦RED⟧कृत-परिरम्भण-चुम्बनया परिरभ्य कृताधर-पानम् ॥ ३ ॥
अनुवाद: नव-पल्लवों की शय्या पर मुझे लिटाकर वे बहुत देर तक मेरे ही वक्ष पर लेटे रहे; मैंने आलिङ्गन-चुम्बन किया तो उन्होंने भी आलिङ्गन करके अधरामृत का पान किया—(उन कृष्ण को…)।

⟦RED⟧अलस-निमीलित-लोचनया पुलकावलि-ललित-कपोलम्।
⟦RED⟧श्रम-जल-सकल-कलेवरया वर-मदन-मदाद् अतिलोलम् ॥ ४ ॥
अनुवाद: मेरे नेत्र आलस्य से मुँद रहे थे; उनके सुन्दर कपोल रोमाञ्च की पंक्तियों से शोभित हो उठे। मेरा सारा शरीर पसीने से भीग गया था और वे श्रेष्ठ प्रेम-मत्तता से अत्यन्त चञ्चल हो उठे—(उन कृष्ण को…)।

⟦RED⟧कोकिल-कल-रव-कूजितया जित-मनसिज-तन्त्र-विचारम्।
⟦RED⟧श्लथ-कुसुमाकुल-कुन्तलया नख-लिखित-घन-स्तन-भारम् ॥ ५ ॥
अनुवाद: मैं कोयल की मधुर कूक के समान कूज रही थी; वे कामशास्त्र के विचार को भी जीत रहे थे। मेरे केश ढीले फूलों से आकुल हो गए थे और उन्होंने नखों से मेरे वक्ष पर रेखाएँ अंकित कर दीं—(उन कृष्ण को…)।

⟦RED⟧चरण-रणित-मणि-नूपुरया परिपूरित-सुरत-वितानम्।
⟦RED⟧मुखर-विशृङ्खल-मेखलया सकच-ग्रह-चुम्बन-दानम् ॥ ६ ॥
अनुवाद: मेरे चरणों के मणि-नूपुर झंकृत हो रहे थे और उन्होंने प्रेम-लीला का विस्तार पूर्ण किया; मेरी मेखला मुखर और अस्त-व्यस्त हो गई थी और उन्होंने केश पकड़कर चुम्बन दिया—(उन कृष्ण को…)।

⟦RED⟧रति-सुख-समय-रसालसया दर-मुकुलित-नयन-सरोजम्।
⟦RED⟧निःसह-निपतित-तनु-लतया मधुसूदनम् उदित-मनोजम् ॥ ७ ॥
अनुवाद: मिलन-सुख के समय मैं रस के आवेश से आलसी हो गई थी, मेरे कमल-नयन अधखुले थे; लता के समान अवश देह से मैं ढह पड़ी—प्रेम में विभोर उन मधुसूदन को (मेरे साथ मिलाओ)।

⟦RED⟧श्री-जयदेव-भणितम् इदम् अतिशय-मधु-रिपु-निधुवन-शीलम्।
⟦RED⟧सुखम् उत्कण्ठित-गोप-वधू-कथितं वितनोतु सलीलम् ॥ ८ ॥
अनुवाद: श्रीजयदेव द्वारा कहा गया, मधुसूदन श्रीकृष्ण की प्रेम-लीला के स्वभाव से युक्त तथा उत्कण्ठिता गोपवधू (श्रीराधा) द्वारा कहा गया यह गीत लीला-पूर्वक सुख का विस्तार करे।`,
  hsr:`हमारें माई स्यामा जू कौ राज

⟦RED⟧हमारें माई स्यामा जू कौ राज ।
⟦RED⟧जाके अधीन सदाई साँवरौ या ब्रज कौ सिरताज॥ [१]
अनुवाद: श्री विठ्ठल विपुल देव कहते हैं कि हमारे प्रेम-रस देश में केवल श्री श्यामा जू (श्री राधा) का ही एकछत्र राज्य है, जिनके प्रेम के अधीन स्वयं ब्रज के शिरोमणि श्री कृष्ण हैं।

⟦RED⟧यह जोरी अविचल वृन्दावन नाहिं आन सों काज ।
⟦RED⟧श्री विट्ठल विपुल बिहारिनि के बल दिन जलधर ज्यौं गाज॥ [२]
— श्री विट्ठल विपुल देव जी की वाणी (२७), राग मल्हार
अनुवाद: यह प्रेममयी जोड़ी (विहारी-विहारिणी जू) वृन्दावन की रस-माधुरी में सदैव तदाकार होकर अविचल रूप से नित्य विहार करती है। हम इस दिव्य जोड़ी के प्रति ऐसे दृढ़ अनन्य हैं कि इनके अतिरिक्त हमारा अन्य किसी से कोई संबंध नहीं है। जिस प्रकार घन के निकट दामिनी प्रफुल्लित होकर गर्जना करती है, उसी प्रकार हम भी उद्घोष करते हैं कि केवल श्री राधा महारानी के बल पर ही हमको नित्य विहार रस की प्राप्ति होती है।`
};

// ── Srimad Bhagavad Gita (18 chapters / 700 shlokas) ────────────────
// The Bengali verse text and Bengali meaning are loaded once, on demand,
// from the maintained open-source data file below and then cached locally.
// Keeping the large scripture outside this already-large bundle makes the
// first screen fast while still making all 700 shlokas available offline
// after the first successful load.
const GITA_ID = 'bg';
const GITA_DATA_URL =
  'https://raw.githubusercontent.com/saikardas2026-ui/srimad-bhagavad-gita-app/main/src/data.ts';
const GITA_CACHE_KEY = 'rjap_gita_bengali_v1';
const GITA_CHAPTER_NAMES = [
  'অর্জুনবিষাদ যোগ',
  'সাংখ্য যোগ',
  'কর্মযোগ',
  'জ্ঞানযোগ',
  'কর্মসংন্যাস যোগ',
  'আত্মসংযম যোগ',
  'জ্ঞানবিজ্ঞান যোগ',
  'অক্ষরব্রহ্ম যোগ',
  'রাজবিদ্যারাজগুহ্য যোগ',
  'বিভূতি যোগ',
  'বিশ্বরূপদর্শন যোগ',
  'ভক্তি যোগ',
  'ক্ষেত্রক্ষেত্রজ্ঞবিভাগ যোগ',
  'গুণত্রয়বিভাগ যোগ',
  'পুরুষোত্তম যোগ',
  'দৈবাসুরসম্পদ্বিভাগ যোগ',
  'শ্রদ্ধাত্রয়বিভাগ যোগ',
  'মোক্ষসংন্যাস যোগ'
];
const GITA_CHAPTER_COUNTS = [46,72,43,42,29,47,30,28,34,42,55,20,35,27,20,24,28,78];
let _gitaLoadPromise = null;
let _gitaReady = false;

// A non-empty placeholder keeps the scripture's 📖 button visible in the
// Krishna folder before the on-demand request has completed.
LYRICS[GITA_ID] =
  '§§ অধ্যায়ঃ ১ - অর্জুনবিষাদ যোগ\n§ শ্লোক ১\nগীতার পাঠ লোড হচ্ছে…';

function _gitaBnNum(n) {
  return String(n).replace(/[0-9]/g, function (d) {
    return '০১২৩৪৫৬৭৮৯'[Number(d)];
  });
}

function _gitaReadField(body, key) {
  // The source is a TypeScript data file whose verse values are ordinary
  // double-quoted strings. Parse only the fields we need; do not evaluate
  // the downloaded source as JavaScript.
  var match = body.match(
    new RegExp('(?:^|\\n)\\s*' + key + ':\\s*"((?:\\\\.|[^"\\\\])*)"', 'm')
  );
  return match ? JSON.parse('"' + match[1] + '"') : '';
}

function _gitaSourceToLyrics(source) {
  var chapters = [];
  var total = 0;

  for (var ch = 1; ch <= 18; ch++) {
    var start = source.indexOf(
      'const CH' + ch + ': Record<number, VerseContent> = {'
    );
    var end = start < 0 ? -1 : source.indexOf('\n};', start);
    if (start < 0 || end < 0) {
      throw new Error('Gita chapter ' + ch + ' is missing');
    }

    var block = source.slice(start, end + 3);
    var entries = [];
    var entryRe = /^\s*(\d+):\s*\{([\s\S]*?)^\s*\},?\s*$/gm;
    var entry;
    while ((entry = entryRe.exec(block))) {
      var verseNumber = Number(entry[1]);
      var body = entry[2];
      var sanskrit = _gitaReadField(body, 'sanskrit');
      var bengali = _gitaReadField(body, 'bengali');
      if (!sanskrit || !bengali) {
        throw new Error('Gita verse ' + ch + '.' + verseNumber + ' is incomplete');
      }
      entries.push({
        number: verseNumber,
        speaker: _gitaReadField(body, 'speaker'),
        sanskrit: sanskrit,
        bengali: bengali
      });
    }

    entries.sort(function (a, b) { return a.number - b.number; });
    if (entries.length !== GITA_CHAPTER_COUNTS[ch - 1]) {
      throw new Error(
        'Gita chapter ' + ch + ' has ' + entries.length + ' verses'
      );
    }
    total += entries.length;
    chapters.push(entries);
  }

  if (total !== 700) throw new Error('Gita contains ' + total + ' verses');

  var output = [];
  chapters.forEach(function (entries, chapterIndex) {
    var chapterNumber = chapterIndex + 1;
    output.push(
      '§§ অধ্যায়ঃ ' + _gitaBnNum(chapterNumber) + ' - ' +
      GITA_CHAPTER_NAMES[chapterIndex]
    );
    entries.forEach(function (verse) {
      output.push(
        '§ শ্লোক ' + _gitaBnNum(verse.number) + '\n' +
        (verse.speaker ? verse.speaker + '\n' : '') +
        verse.sanskrit + '\nঅর্থ: ' + verse.bengali
      );
    });
  });
  return output.join('\n');
}

function _gitaLooksComplete(text) {
  return typeof text === 'string' &&
    (text.match(/^§ শ্লোক /gm) || []).length === 700;
}

// Restore a successful previous load without blocking startup.
try {
  var _gitaCached = localStorage.getItem(GITA_CACHE_KEY);
  if (_gitaLooksComplete(_gitaCached)) {
    LYRICS[GITA_ID] = _gitaCached;
    _gitaReady = true;
  }
} catch (_) {}

function loadGitaLyrics() {
  if (_gitaReady) return Promise.resolve(LYRICS[GITA_ID]);
  if (_gitaLoadPromise) return _gitaLoadPromise;

  _gitaLoadPromise = fetch(GITA_DATA_URL)
    .then(function (response) {
      if (!response.ok) throw new Error('Gita data request failed');
      return response.text();
    })
    .then(function (source) {
      var lyrics = _gitaSourceToLyrics(source);
      LYRICS[GITA_ID] = lyrics;
      _gitaReady = true;
      try { localStorage.setItem(GITA_CACHE_KEY, lyrics); } catch (_) {}
      return lyrics;
    })
    .catch(function (error) {
      _gitaLoadPromise = null;
      throw error;
    });
  return _gitaLoadPromise;
}

window.loadGitaLyrics = loadGitaLyrics;
window.isGitaReady = function () { return _gitaReady; };

// ═══════════════════════════════════════════════════════
// SECTIONED-STOTRAM PICKER (svb, blv, …)
// All UI/logic for stotrams that have numbered sub-sections
// lives here so updates can be made in this file alone.
// Styling lives in style-stotram.css (.sts-* classes).
//
// Depends on these globals defined in app.js:
//   getEffectiveLyrics(id)  _renderVerse(idx,prev)  _initSwipeHandler()
//   _verses (array)         _verseIdx (number)
// ═══════════════════════════════════════════════════════
(function (global) {
  // Map of stotram-id → display title shown above the picker grid.
  var SECTIONED = {
    svb: 'শ্রী হিত সেবক বাণী',
    blv: 'বয়ালীস লীলা',
    gg:  'গীতগোবিন্দম্',
    bg:  'শ্রীমদ্ভগবদ্গীতা'
  };

  // Stotrams using two-level §§ / § hierarchy
  var TWO_LEVEL = { gg: true, bg: true };

  // Safely remove a #sts-picker (or similar) overlay. Plain el.remove() can
  // leave a visual "ghost" of the element on screen in iOS Safari, because
  // .sts-picker uses -webkit-overflow-scrolling:touch, which puts it on its
  // own GPU compositing layer — WebKit sometimes fails to repaint that
  // screen region when the layer is torn down mid-navigation, so the last
  // frame it painted (e.g. the geetam list) stays visible, overlapping
  // whatever renders next (e.g. the opened song's lyrics). Hiding the
  // element and forcing a reflow *before* removing it reliably avoids this.
  function _killPicker(el) {
    if (!el) return;
    el.style.display = 'none';
    void el.offsetHeight; // force a reflow/repaint before removal
    el.remove();
  }

  // Convert a Bengali-numeral string (e.g. "১২") to a JS number.
  var _bnDigits = '০১২৩৪৫৬৭৮৯';
  function _bnToNum(s) {
    var out = '';
    for (var i = 0; i < s.length; i++) {
      var di = _bnDigits.indexOf(s[i]);
      out += di === -1 ? s[i] : String(di);
    }
    return parseInt(out, 10);
  }

  var _sections = [];          // [{title, content}]
  var _activeId = null;        // current sectioned-stotram id
  var _inSectionView = false;
  function _isGitaMode() { return _activeId === 'bg'; }
  global.setGitaVerseTitle = function (idx) {
    if (_activeId !== 'bg') return;
    var title = document.getElementById('lmTitle');
    if (!title) return;
    title.textContent = 'শ্লোক ' + String(idx + 1).replace(/[0-9]/g, function (d) {
      return '০১২৩৪৫৬৭৮৯'[Number(d)];
    });
  };

  // ── Parse GG two-level: §§ = sarga, § = geetam ───────────────────────
  // Returns [{title, subs:[{title,content}], preamble}]
  function parseGG(ly) {
    var sargas = [];
    var curSarga = null;
    var curGeetam = null;
    var curLines = [];
    var preambleLines = [];
    var inPreamble = false;

    function flushGeetam() {
      if (curGeetam !== null && curSarga) {
        curSarga.subs.push({ title: curGeetam, content: curLines.join('\n').trim() });
      }
      curGeetam = null; curLines = [];
    }
    function flushSarga() {
      flushGeetam();
      if (curSarga) sargas.push(curSarga);
      curSarga = null;
    }

    var lines = ly.split('\n');
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if (line.startsWith('§§ ')) {
        flushSarga();
        var title = line.slice(3).trim();
        if (title === 'পূর্বভূমিকা') {
          inPreamble = true;
          curSarga = { title: title, subs: [], preamble: '' };
        } else {
          inPreamble = false;
          curSarga = { title: title, subs: [], preamble: '' };
        }
        continue;
      }
      if (line.startsWith('§ ')) {
        if (inPreamble && curSarga) {
          curSarga.preamble = preambleLines.join('\n').trim();
          preambleLines = [];
          inPreamble = false;
        }
        flushGeetam();
        curGeetam = line.slice(2).trim();
        continue;
      }
      if (inPreamble) {
        preambleLines.push(lines[i]);
      } else if (curGeetam !== null) {
        curLines.push(lines[i]);
      } else if (curSarga) {
        // Between §§ and first §: sarga preamble
        curSarga.preamble = (curSarga.preamble || '') + lines[i] + '\n';
      }
    }
    // Flush last preamble section
    if (inPreamble && curSarga) {
      curSarga.preamble = preambleLines.join('\n').trim();
    }
    flushSarga();
    return sargas;
  }

  var _ggSargas = [];   // parsed two-level structure for gg
  var _curSargaIdx = -1;

  // ── Show top-level Sarga picker for GG ───────────────────────────────
  function showSargaPicker(id) {
    _activeId = id;
    var ly = (typeof getEffectiveLyrics === 'function') ? getEffectiveLyrics(id) : '';
    _ggSargas = parseGG(ly || '');

    var lmo    = document.getElementById('lmo');
    var lmb    = document.getElementById('lmb');
    var lmNav  = document.getElementById('lmNav');
    var lmTitle= document.getElementById('lmTitle');
    var fsCtrl = document.getElementById('lyr-fs-ctrl');
    var oldWrap= document.getElementById('lm-translate-wrap');
    if (oldWrap) oldWrap.remove();
    if (lmb)    lmb.style.display    = 'none';
    if (lmNav)  lmNav.style.display  = 'none';
    if (lmTitle){ lmTitle.textContent = ''; lmTitle.style.display = 'none'; }
    if (fsCtrl) fsCtrl.style.display = 'none';
    ['sts-picker','sts-sub-picker'].forEach(function(pid){
      _killPicker(document.getElementById(pid));
    });

    var picker = document.createElement('div');
    picker.id = 'sts-picker';
    picker.className = 'sts-picker' + (window.innerWidth >= 600 ? ' sts-wide' : '');

    var titleDiv = document.createElement('div');
    titleDiv.className = 'sts-picker-title';
    titleDiv.textContent = SECTIONED[id] || '';
    picker.appendChild(titleDiv);

    var subtitle = document.createElement('div');
    subtitle.className = 'sts-picker-subtitle';
    subtitle.textContent = _isGitaMode() ? 'অধ্যায় নির্বাচন করুন' : 'সর্গ নির্বাচন করুন';
    picker.appendChild(subtitle);

    var glowColors = ['#ffd700','#ffaa00','#ff6bff','#00e5ff','#7dff6b',
      '#ff6b6b','#ffd700','#b388ff','#00ffcc','#ffaa00','#ffd700','#ff6bff','#00e5ff'];

    var grid = document.createElement('div');
    grid.className = 'sts-picker-grid';
    var rows = Math.max(1, Math.ceil(_ggSargas.length / 2));
    grid.style.gridTemplateRows = 'repeat(' + rows + ',auto)';

    _ggSargas.forEach(function(sarga, idx) {
      var btn = document.createElement('button');
      var gc = glowColors[idx % glowColors.length];
      btn.className = 'sts-btn';
      btn.style.setProperty('--gc', gc);
      btn.style.setProperty('--pd', (2.8 + (idx%5)*0.4).toFixed(1)+'s');
      btn.style.setProperty('--cd', (8 + (idx%4)*1.5).toFixed(1)+'s');
      btn.style.setProperty('--fd', (idx*0.045).toFixed(2)+'s');
      btn.style.setProperty('--od', '-'+(idx*0.6).toFixed(1)+'s');
      btn.style.setProperty('--ad', (idx*0.045).toFixed(2)+'s');

      var numSpan = document.createElement('span');
      numSpan.className = 'sts-btn-num';
      if (sarga.title === 'পূর্বভূমিকা') {
        numSpan.style.display = 'none';
      } else {
        var nm = sarga.title.match(/[০-৯]+/);
        numSpan.textContent = nm ? nm[0] : String(idx + 1);
      }

      var nameSpan = document.createElement('span');
      nameSpan.className = 'sts-btn-name';
      nameSpan.textContent = sarga.title === 'পূর্বভূমিকা' ? 'পূর্বভূমিকা' : sarga.title;

      btn.appendChild(numSpan);
      btn.appendChild(nameSpan);
      btn.onclick = (function(i){ return function(){ showGeetamPicker(i); }; })(idx);
      grid.appendChild(btn);
    });
    picker.appendChild(grid);

    var lmd = document.querySelector('.lmd');
    if (lmd) lmd.appendChild(picker);
    if (lmo) lmo.classList.add('show');
  }

  // ── Show Geetam sub-picker for one Sarga ─────────────────────────────
  function showGeetamPicker(sargaIdx) {
    _curSargaIdx = sargaIdx;
    var sarga = _ggSargas[sargaIdx];
    if (!sarga) return;

    var oldPicker = document.getElementById('sts-picker');
    _killPicker(oldPicker);
    if (sarga.title === 'পূর্বভূমিকা') {
      openGeetam(sargaIdx, -1);
      return;
    }

    var picker = document.createElement('div');
    picker.id = 'sts-picker';
    picker.className = 'sts-picker' + (window.innerWidth >= 600 ? ' sts-wide' : '');

    // Back button
    var backBtn = document.createElement('button');
    backBtn.className = 'sts-back-btn';
    backBtn.textContent = '←';
    backBtn.setAttribute('aria-label', _isGitaMode() ? 'অধ্যায় তালিকা' : 'সর্গ তালিকা');
    backBtn.onclick = function() { showSargaPicker(_activeId); };
    picker.appendChild(backBtn);

    var titleDiv = document.createElement('div');
    titleDiv.className = 'sts-picker-title';
    titleDiv.textContent = sarga.title;
    picker.appendChild(titleDiv);

    var subtitle = document.createElement('div');
    subtitle.className = 'sts-picker-subtitle';
    subtitle.textContent = _isGitaMode() ? 'শ্লোক নির্বাচন করুন' : 'গীতম্ নির্বাচন করুন';
    picker.appendChild(subtitle);

    var glowColors = ['#ffd700','#ffaa00','#ff6bff','#00e5ff','#7dff6b',
      '#ff6b6b','#ffd700','#b388ff','#00ffcc','#ffaa00'];

    // Preamble button (if sarga has preamble text)
    var items = [];
    sarga.subs.forEach(function(g, i){ items.push({ label: g.title, subIdx: i }); });

    // Sarga number (for building the same "gg_<sarga#>_<geetam#>" audio
    // key openGeetam uses) — lets the picker show a 🎶 badge on any
    // geetam that actually has a recorded clip in _AUDIO_STOTRAMS.gg.tracks.
    var _sNumMatch = sarga.title.match(/[০-৯]+/);
    var _sNum = _sNumMatch ? _bnToNum(_sNumMatch[0]) : (sargaIdx + 1);
    var _ggTracks = (typeof _AUDIO_STOTRAMS !== 'undefined' && _AUDIO_STOTRAMS.gg && _AUDIO_STOTRAMS.gg.tracks) || {};

    var _ggYt = (typeof _AUDIO_STOTRAMS !== 'undefined' && _AUDIO_STOTRAMS.gg && _AUDIO_STOTRAMS.gg.ytTracks) || {};
    var grid = document.createElement('div');
    grid.className = 'sts-picker-grid';
    var rows = Math.max(1, Math.ceil(items.length / 2));
    grid.style.gridTemplateRows = 'repeat(' + rows + ',auto)';

    items.forEach(function(item, idx) {
      var btn = document.createElement('button');
      var gc = glowColors[idx % glowColors.length];
      btn.className = 'sts-btn';
      btn.style.setProperty('--gc', gc);
      btn.style.setProperty('--pd', (2.8+(idx%5)*0.4).toFixed(1)+'s');
      btn.style.setProperty('--cd', (8+(idx%4)*1.5).toFixed(1)+'s');
      btn.style.setProperty('--fd', (idx*0.045).toFixed(2)+'s');
      btn.style.setProperty('--od', '-'+(idx*0.6).toFixed(1)+'s');
      btn.style.setProperty('--ad', (idx*0.045).toFixed(2)+'s');

      var numSpan = document.createElement('span');
      numSpan.className = 'sts-btn-num';
      numSpan.textContent = item.subIdx === -1 ? '॥' : String(idx + 1);

      var nameSpan = document.createElement('span');
      nameSpan.className = 'sts-btn-name';
      // Truncate long geetam titles
      var t = item.label;
      if (t.length > 40) t = t.slice(0, 38) + '…';
      var _gk = 'gg_' + _sNum + '_' + (item.subIdx + 1);
      var _hasAudio = item.subIdx !== -1 && (!!_ggTracks[_gk] || !!_ggYt[_gk]);
      nameSpan.textContent = t + (_hasAudio ? ' 🎶' : '');

      btn.appendChild(numSpan);
      btn.appendChild(nameSpan);
      btn.onclick = (function(si){ return function(){ openGeetam(sargaIdx, si); }; })(item.subIdx);
      grid.appendChild(btn);
    });
    picker.appendChild(grid);

    // Pre-load the hidden YouTube player(s) of this sarga's YouTube songs so
    // the song starts the instant it is opened.
    try {
      var _wl = [];
      Object.keys(_ggYt).forEach(function (k) {
        if (k.indexOf('gg_' + _sNum + '_') === 0) _wl.push({ key: 'gg:' + k, vid: _ggYt[k], start: 0 });
      });
      if (typeof _hcjWarmSet === 'function') _hcjWarmSet(_wl);
    } catch (_e) {}

    var lmd = document.querySelector('.lmd');
    if (lmd) lmd.appendChild(picker);
  }

  // ── Open one Geetam (or sarga preamble) in verse reader ──────────────
  function openGeetam(sargaIdx, subIdx) {
    var sarga = _ggSargas[sargaIdx];
    if (!sarga) return;

    var content, title;
    if (subIdx === -1) {
      // preamble of sarga (or whole preamble section)
      content = sarga.preamble || sarga.subs.map(function(s){return s.content;}).join('\n\n');
      title = sarga.title;
    } else {
      var geetam = sarga.subs[subIdx];
      if (!geetam) return;
      content = geetam.content;
      title = geetam.title;
    }

    // Audio key for gg (Geet Govindam): "gg_<sarga#>_<geetam#>" — read by
    // app.js's audio player (_AUDIO_STOTRAMS.gg.tracks). Every geetam here
    // renders as a single verse card (idx is always 0), so the player can't
    // tell songs apart by verse index the way other stotrams do — this key
    // is how it knows which song (if any) has a clip. Stop any audio that
    // was playing for the previous geetam before switching.
    if (_activeId === 'gg' && subIdx !== -1) {
      var _sNumMatch = sarga.title.match(/[০-৯]+/);
      var _sNum = _sNumMatch ? _bnToNum(_sNumMatch[0]) : (sargaIdx + 1);
      window._ggAudioKey = 'gg_' + _sNum + '_' + (subIdx + 1);
      window._bgChapterNum = null;
    } else if (_activeId === 'bg' && subIdx !== -1) {
      // Gita audio path is "bg_<chapter#>_<shlok#>.mp3" (see app.js's
      // _AUDIO_STOTRAMS.bg / _hcjAudioPath) — chapter number comes from
      // the sarga's own Bengali numeral, same extraction gg uses for its
      // sarga number.
      var _chNumMatch = sarga.title.match(/[০-৯]+/);
      window._bgChapterNum = _chNumMatch ? _bnToNum(_chNumMatch[0]) : (sargaIdx + 1);
      window._ggAudioKey = null;
    } else {
      window._ggAudioKey = null;
      window._bgChapterNum = null;
    }
    if (typeof _hcjStopAudio === 'function') _hcjStopAudio();

    _inSectionView = true;
    var picker = document.getElementById('sts-picker');
    _killPicker(picker);

    var lmb   = document.getElementById('lmb');
    var lmNav = document.getElementById('lmNav');
    if (lmb)   lmb.style.display = '';
    if (lmNav) lmNav.style.display = '';

    var fsCtrl = document.getElementById('lyr-fs-ctrl');
    if (fsCtrl) fsCtrl.style.display = '';

    var lmTitle = document.getElementById('lmTitle');
    if (lmTitle) {
      lmTitle.style.display = '';
      var shortTitle = title.length > 50 ? title.slice(0,48)+'…' : title;
      lmTitle.textContent = shortTitle;
    }

    if (typeof _verses !== 'undefined') {
      if (_activeId === 'bg' && subIdx !== -1) {
        // Gita chapters are a real verse sequence: keep the whole chapter
        // in the reader so the bottom previous/next arrows can move through
        // every shloka instead of rendering only the tapped one.
        _verses = sarga.subs.map(function (verse) {
          return verse.content.trim();
        });
        _verseIdx = subIdx;
        if (typeof _verseNavLocked !== 'undefined') _verseNavLocked = false;
      } else {
        // Geetam entries remain single-card readers.
        _verses = [content.trim()];
        _verseIdx = 0;
      }
      if (typeof _renderVerse === 'function') _renderVerse(_verseIdx, null);
      if (typeof _initSwipeHandler === 'function') _initSwipeHandler();
      // YouTube-backed geetam: use the pre-loaded player and start playing right away (same tap).
      if (_activeId === 'gg' && subIdx !== -1 && typeof _hcjAdoptWarm === 'function') {
        try { _hcjAdoptWarm(true); } catch (_e) {}
      }
    }

    // Back button in verse title bar
    var existingBack = document.getElementById('sts-verse-back');
    if (existingBack) existingBack.remove();
    var backBtn = document.createElement('button');
    backBtn.id = 'sts-verse-back';
    backBtn.className = 'sts-back-btn';
    backBtn.textContent = '←';
    backBtn.setAttribute('aria-label', _isGitaMode() ? 'শ্লোক তালিকা' : 'গীতম্ তালিকা');
    backBtn.onclick = function() {
      if (typeof _hcjStopAudio === 'function') _hcjStopAudio();
      window._ggAudioKey = null;
      window._bgChapterNum = null;
      backBtn.remove();
      // Leave the reader completely before rebuilding the sloka picker.
      // Keeping lmb/lmNav visible makes the new picker render over the old
      // verse card, which is especially noticeable on mobile browsers.
      var lmbBack = document.getElementById('lmb');
      var lmNavBack = document.getElementById('lmNav');
      var fsCtrlBack = document.getElementById('lyr-fs-ctrl');
      var translateBack = document.getElementById('lm-translate-wrap');
      var titleBack = document.getElementById('lmTitle');
      if (lmbBack) lmbBack.style.display = 'none';
      if (lmNavBack) lmNavBack.style.display = 'none';
      if (fsCtrlBack) fsCtrlBack.style.display = 'none';
      if (translateBack) translateBack.remove();
      if (titleBack) {
        titleBack.textContent = '';
        titleBack.style.display = 'none';
      }
      var lmoBack = document.getElementById('lmo');
      if (lmoBack) lmoBack.classList.remove('has-sts-back');
      showGeetamPicker(sargaIdx);
      _inSectionView = false;
    };
    if (lmTitle) lmTitle.parentNode.insertBefore(backBtn, lmTitle);
    var lmoFwd = document.getElementById('lmo');
    if (lmoFwd) lmoFwd.classList.add('has-sts-back');
  }

  // ── Parse lyrics into sections by Bengali-numeral headings ────────────
  function parseSections(ly) {
    var lines = ly.split('\n');
    var sections = [];
    var curTitle = null;
    var curLines = [];

    function isTitle(line) {
      if (/^[০-৯]+\./.test(line) && line.length < 100) return true;
      // SVB-only: phalashruti section (no numeral): শ্রী সেবক বাণী-ফল স্তুতি
      if (/ফল\s*(স্তুতি|শ্রুতি)/.test(line) && line.length < 100) return true;
      return false;
    }
    function flush() {
      if (curTitle && curLines.length > 0) {
        sections.push({ title: curTitle, content: curLines.join('\n').trim() });
      }
      curTitle = null; curLines = [];
    }

    for (var i = 0; i < lines.length; i++) {
      var raw = lines[i];
      var line = raw.trim();
      // Section closing marker: ! … !
      if (line.startsWith('!') && line.endsWith('!')) { flush(); continue; }
      if (isTitle(line)) {
        if (curTitle) flush();
        curTitle = line;
        continue;
      }
      if (curTitle) curLines.push(raw);
    }
    flush();
    return sections;
  }

  function isSectioned(id) { return Object.prototype.hasOwnProperty.call(SECTIONED, id); }
  function isTwoLevel(id)  { return Object.prototype.hasOwnProperty.call(TWO_LEVEL, id); }

  // ── Show the section picker grid ──────────────────────────────────────
  function showPicker(id) {
    if (isTwoLevel(id)) { showSargaPicker(id); return; }
    _activeId = id;
    var ly = (typeof getEffectiveLyrics === 'function') ? getEffectiveLyrics(id) : '';
    _sections = parseSections(ly || '');
    _inSectionView = false;

    var lmo = document.getElementById('lmo');
    var lmTitle = document.getElementById('lmTitle');
    if (lmTitle) { lmTitle.textContent = SECTIONED[id] || ''; lmTitle.style.display = 'none'; }

    // Hide verse-reader chrome
    var lmb   = document.getElementById('lmb');
    var lmNav = document.getElementById('lmNav');
    if (lmb)   lmb.style.display   = 'none';
    if (lmNav) lmNav.style.display = 'none';

    var oldWrap = document.getElementById('lm-translate-wrap');
    if (oldWrap) oldWrap.remove();

    var oldPicker = document.getElementById('sts-picker');
    _killPicker(oldPicker);

    var fsCtrl = document.getElementById('lyr-fs-ctrl');
    if (fsCtrl) fsCtrl.style.display = 'none';

    // Responsive numbers
    var vw = window.innerWidth;
    var isWide = vw >= 600;

    var picker = document.createElement('div');
    picker.id = 'sts-picker';
    picker.className = 'sts-picker' + (isWide ? ' sts-wide' : '');

    var titleDiv = document.createElement('div');
    titleDiv.id  = 'sts-picker-title';
    titleDiv.className = 'sts-picker-title';
    titleDiv.textContent = SECTIONED[id] || '';
    picker.appendChild(titleDiv);

    var subtitle = document.createElement('div');
    subtitle.className = 'sts-picker-subtitle';
    subtitle.textContent = 'বিভাগ নির্বাচন করুন';
    picker.appendChild(subtitle);

    // Grid (two columns, balanced rows)
    var grid = document.createElement('div');
    grid.className = 'sts-picker-grid';
    var rows = Math.max(1, Math.ceil(_sections.length / 2));
    grid.style.gridTemplateRows = 'repeat(' + rows + ',auto)';

    var glowColors = [
      '#ffd700','#ffaa00','#ff6bff','#00e5ff','#7dff6b',
      '#ff6b6b','#ffd700','#b388ff','#00ffcc','#ffaa00',
      '#ffd700','#ff6bff','#00e5ff','#7dff6b','#ff6b6b',
      '#ffd700','#b388ff'
    ];

    _sections.forEach(function (sec, idx) {
      var btn = document.createElement('button');
      var gc        = glowColors[idx % glowColors.length];
      var pulseDur  = (2.8 + (idx % 5) * 0.4).toFixed(1) + 's';
      var colorDur  = (8   + (idx % 4) * 1.5).toFixed(1) + 's';
      var fadeDelay = (idx * 0.045).toFixed(2) + 's';
      var colorOff  = '-' + (idx * 0.6).toFixed(1) + 's';

      btn.className = 'sts-btn';
      btn.style.setProperty('--gc', gc);
      btn.style.setProperty('--pd', pulseDur);
      btn.style.setProperty('--cd', colorDur);
      btn.style.setProperty('--fd', fadeDelay);
      btn.style.setProperty('--od', colorOff);
      btn.style.setProperty('--ad', fadeDelay);

      var numSpan = document.createElement('span');
      numSpan.className = 'sts-btn-num';
      numSpan.textContent = String(idx + 1);

      var nameSpan = document.createElement('span');
      nameSpan.className = 'sts-btn-name';
      nameSpan.textContent = sec.title.replace(/^[০-৯]+\.\s*/, '');

      btn.appendChild(numSpan);
      btn.appendChild(nameSpan);
      btn.onclick = function () { openSection(idx); };
      grid.appendChild(btn);
    });
    picker.appendChild(grid);

    var lmd = document.querySelector('.lmd');
    if (lmd) lmd.appendChild(picker);
    if (lmo) lmo.classList.add('show');
  }

  // ── Open one section in the verse reader ──────────────────────────────
  function openSection(idx) {
    var sec = _sections[idx];
    if (!sec) return;

    _inSectionView = true;

    var picker = document.getElementById('sts-picker');
    _killPicker(picker);

    var lmb   = document.getElementById('lmb');
    var lmNav = document.getElementById('lmNav');
    if (lmb)   lmb.style.display   = '';
    if (lmNav) lmNav.style.display = '';

    var fsCtrl = document.getElementById('lyr-fs-ctrl');
    if (fsCtrl) fsCtrl.style.display = '';

    var lmTitle = document.getElementById('lmTitle');
    if (lmTitle) {
      lmTitle.style.display = '';
      lmTitle.textContent = sec.title.replace(/^[০-৯]+\.\s*/, '');
    }

    // Back-to-sections button
    var existing = document.getElementById('sts-back-btn');
    if (!existing) {
      var backBtn = document.createElement('button');
      backBtn.id  = 'sts-back-btn';
      backBtn.className = 'sts-back-btn';
      backBtn.textContent = '←';
      backBtn.setAttribute('aria-label', 'বিভাগ তালিকা');
      backBtn.onclick = function () {
        _inSectionView = false;
        var old = document.getElementById('sts-back-btn');
        if (old) old.remove();
        var lmb2   = document.getElementById('lmb');
        var lmNav2 = document.getElementById('lmNav');
        if (lmb2)   lmb2.style.display   = 'none';
        if (lmNav2) lmNav2.style.display = 'none';
        var w2 = document.getElementById('lm-translate-wrap');
        if (w2) w2.remove();
        showPicker(_activeId);
      };
      var lmo = document.getElementById('lmo');
      if (lmo) lmo.appendChild(backBtn);
    }

    // Split section content into verses, merge orphan অর্থ-only blocks back
    var allVerses = sec.content
      .split(/\n{2,}/)
      .map(function (b) { return b.trim(); })
      .filter(function (b) { return b.length > 0; });

    var merged = [];
    for (var i = 0; i < allVerses.length; i++) {
      var v = allVerses[i];
      var linesOnly = v.split('\n').filter(function (l) { return l.trim().length > 0; });
      var allArtha = linesOnly.length > 0 && linesOnly.every(function (l) {
        return /^অর্থ\s*:/.test(l.trim());
      });
      if (allArtha && merged.length > 0) {
        merged[merged.length - 1] += '\n\n' + v;
      } else {
        merged.push(v);
      }
    }

    // FIX: app.js declares `_verses`/`_verseIdx` with `let` (script-scoped),
    // so assigning to window._verses does NOT update them. Route through
    // showLyrics() by temporarily un-sectioning this id and overriding the
    // lyrics getter to return only the chosen section's verses.
    var idToOpen        = _activeId;
    var savedTitle      = SECTIONED[idToOpen];
    var savedGetLyrics  = window.getEffectiveLyrics;
    var sectionLyrics   = merged.join('\n\n');

    delete SECTIONED[idToOpen];
    window.getEffectiveLyrics = function (qid) {
      if (qid === idToOpen) return sectionLyrics;
      return savedGetLyrics.apply(this, arguments);
    };
    try {
      if (typeof window.showLyrics === 'function') {
        window.showLyrics(idToOpen);
      }
    } finally {
      window.getEffectiveLyrics = savedGetLyrics;
      SECTIONED[idToOpen] = savedTitle;
    }

    // Re-apply section title (showLyrics overwrites lmTitle with stotram name)
    var lmTitle2 = document.getElementById('lmTitle');
    if (lmTitle2) lmTitle2.textContent = sec.title.replace(/^[০-৯]+\.\s*/, '');

    // Re-apply radha theme to the card (svb/blv aren't in shiv/radha lists
    // so showLyrics clears data-theme).
    var cardEl = document.querySelector('.lm-water-card');
    if (cardEl) cardEl.setAttribute('data-theme', 'radha');
    var lmoEl = document.getElementById('lmo');
    if (lmoEl) lmoEl.setAttribute('data-bg', 'radha');
  }

  // ── Reset, called by app.js when the lyrics modal is closed ───────────
  function reset() {
    _inSectionView = false;
    _sections = [];
    _activeId = null;
    _ggSargas = [];
    _curSargaIdx = -1;
    window._ggAudioKey = null;
    window._bgChapterNum = null;
    _killPicker(document.getElementById('sts-picker'));
    _killPicker(document.getElementById('sts-sub-picker'));
    var b  = document.getElementById('sts-verse-back');  if (b)  b.remove();
    var b2 = document.getElementById('sts-back-btn');    if (b2) b2.remove();
    var lmoReset = document.getElementById('lmo');
    if (lmoReset) lmoReset.classList.remove('has-sts-back');
  }

  global.StotramSections = {
    isSectioned:    isSectioned,
    isTwoLevel:     isTwoLevel,
    show:           showPicker,
    reset:          reset,
    parse:          parseSections,
    parseGG:        parseGG,
    inSectionView:  function () { return _inSectionView; }
  };
})(window);
